import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useParams, useHistory } from 'react-router-dom'; // For route params
// import './ProductDetail.css';

const ProductDetail = () => {
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  
  const { id } = useParams(); // Get product ID from URL
  const history = useHistory();

  useEffect(() => {
    fetchProductDetail();
  }, [id]);

  const fetchProductDetail = async () => {
    try {
      const response = await axios.get(`http://localhost:8080/api/products/${id}`);
      setProduct(response.data);
      setLoading(false);
    } catch (err) {
      setError('Failed to fetch product details. Please try again.');
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="loading">
        <div className="spinner"></div>
        <p>Loading product details...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="error">
        <p>{error}</p>
        <button onClick={fetchProductDetail}>Retry</button>
      </div>
    );
  }

  return (
    <div className="product-detail">
      {product ? (
        <>
          <h1>{product.name}</h1>
          <p><strong>Price:</strong> ₹{product.price}</p>
          <p><strong>Quantity:</strong> {product.quantity}</p>
          <p><strong>Description:</strong> {product.description}</p>
          <p><strong>Listed on:</strong> {product.listingDate}</p>
          <p><strong>Farmer:</strong> {product.farmer?.name || 'Unknown'}</p>

          <button onClick={() => history.goBack()} className="back-button">Go Back</button>
        </>
      ) : (
        <p>Product not found!</p>
      )}
    </div>
  );
};

export default ProductDetail;
